read_code 1: // Package aegisassets exposes the schemas and bundled python-web pack carried
2: // inside the static Aegis binary. Runtime consumers materialize them into a
3: // content-addressed user cache only when an external tool needs a real path.
4: package aegisassets
5: 
6: import (
7: 	"crypto/sha256"
8: 	"embed"
9: 	"fmt"
10: 	"io/fs"
11: 	"os"
12: 	"path/filepath"
13: 	"sort"
14: )
15: 
16: // FS is the immutable distribution payload. These files remain the source
17: // tree's canonical schemas/pack; go:embed does not create a second copy.
18: //
19: //go:embed schemas/*.json packs/python-web
20: var FS embed.FS
21: 
22: // Materialize writes the embedded payload beneath cacheRoot/assets/<hash> and
23: // returns concrete paths for libraries and external tools that require them.
24: func Materialize(cacheRoot string) (schemasDir, packDir string, err error) {
25: 	if cacheRoot == "" {
26: 		return "", "", fmt.Errorf("assets: cache root is empty")
27: 	}
28: 	paths := []string{}
29: 	if err := fs.WalkDir(FS, ".", func(path string, d fs.DirEntry, walkErr error) error {
30: 		if walkErr != nil {
31: 			return walkErr
32: 		}
33: 		if !d.IsDir() {
34: 			paths = append(paths, path)
35: 		}
36: 		return nil
37: 	}); err != nil {
38: 		return "", "", err
39: 	}
40: 	sort.Strings(paths)
41: 	h := sha256.New()
42: 	for _, path := range paths {
43: 		data, readErr := FS.ReadFile(path)
44: 		if readErr != nil {
45: 			return "", "", readErr
46: 		}
47: 		_, _ = h.Write([]byte(path))
48: 		_, _ = h.Write([]byte{0})
49: 		_, _ = h.Write(data)
50: 	}
51: 	root := filepath.Join(cacheRoot, "assets", fmt.Sprintf("%x", h.Sum(nil))[:16])
52: 	for _, path := range paths {
53: 		data, readErr := FS.ReadFile(path)
54: 		if readErr != nil {
55: 			return "", "", readErr
56: 		}
57: 		destination := filepath.Join(root, filepath.FromSlash(path))
58: 		if err := materializeFile(destination, data); err != nil {
59: 			return "", "", err
60: 		}
61: 	}
62: 	return filepath.Join(root, "schemas"), filepath.Join(root, "packs", "python-web"), nil
63: }
64: 
65: func materializeFile(path string, data []byte) error {
66: 	if existing, err := os.ReadFile(path); err == nil {
67: 		if string(existing) == string(data) {
68: 			return nil
69: 		}
70: 	}
71: 	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
72: 		return fmt.Errorf("assets: mkdir %s: %w", filepath.Dir(path), err)
73: 	}
74: 	tmp, err := os.CreateTemp(filepath.Dir(path), ".aegis-asset-*")
75: 	if err != nil {
76: 		return fmt.Errorf("assets: create temp: %w", err)
77: 	}
78: 	tmpPath := tmp.Name()
79: 	committed := false
80: 	defer func() {
81: 		_ = tmp.Close()
82: 		if !committed {
83: 			_ = os.Remove(tmpPath)
84: 		}
85: 	}()
86: 	if err := tmp.Chmod(0o600); err != nil {
87: 		return err
88: 	}
89: 	if _, err := tmp.Write(data); err != nil {
90: 		return err
91: 	}
92: 	if err := tmp.Sync(); err != nil {
93: 		return err
94: 	}
95: 	if err := tmp.Close(); err != nil {
96: 		return err
97: 	}
98: 	if err := os.Rename(tmpPath, path); err != nil {
99: 		return fmt.Errorf("assets: install %s: %w", path, err)
100: 	}
101: 	committed = true
102: 	return nil
103: }
