25: type flexibleStrings []string
26: 
27: func (f *flexibleStrings) UnmarshalJSON(data []byte) error {
28: 	if string(data) == "null" || len(data) == 0 {
29: 		*f = nil
30: 		return nil
31: 	}
32: 	var single string
33: 	if json.Unmarshal(data, &single) == nil {
34: 		*f = []string{single}
35: 		return nil
36: 	}
37: 	var values []any
38: 	if err := json.Unmarshal(data, &values); err != nil {
39: 		return err
40: 	}
41: 	out := make([]string, 0, len(values))
42: 	for _, value := range values {
43: 		switch item := value.(type) {
44: 		case string:
45: 			out = append(out, item)
46: 		case map[string]any:
47: 			file, _ := item["file"].(string)
48: 			line, _ := item["line"].(float64)
49: 			if file != "" && line >= 1 {
50: 				out = append(out, fmt.Sprintf("%s:%d", file, int(line)))
51: 			}
52: 		}
53: 	}
54: 	*f = out
55: 	return nil
56: }
