58: type reviewCandidate struct {
59: 	File               string          `json:"file"`
60: 	Line               int             `json:"line"`
61: 	Symbol             string          `json:"symbol"`
62: 	Type               string          `json:"type"`
63: 	SuspectedVulnClass string          `json:"suspected_vuln_class"`
64: 	CWE                string          `json:"cwe"`
65: 	Impact             string          `json:"impact"`
66: 	Evidence           flexibleStrings `json:"evidence"`
67: 	Chain              flexibleStrings `json:"chain"`
68: 	Rationale          string          `json:"rationale"`
69: 	PriorityHint       string          `json:"priority_hint"`
70: }
