72: func decodeReviewCandidates(text string) ([]reviewCandidate, error) {
73: 	var lastErr error
74: 	for _, payload := range reviewJSONPayloads(text) {
75: 		var direct []reviewCandidate
76: 		if err := json.Unmarshal([]byte(payload), &direct); err == nil {
77: 			return direct, nil
78: 		}
79: 		var wrapped struct {
80: 			Candidates []reviewCandidate `json:"candidates"`
81: 			Findings   []reviewCandidate `json:"findings"`
82: 		}
83: 		if err := json.Unmarshal([]byte(payload), &wrapped); err != nil {
84: 			lastErr = err
85: 			continue
86: 		}
87: 		if wrapped.Candidates != nil {
88: 			return wrapped.Candidates, nil
89: 		}
90: 		if wrapped.Findings != nil {
91: 			return wrapped.Findings, nil
92: 		}
93: 		lastErr = errors.New("回應必須是 JSON array 或包含 candidates/findings array 的物件")
94: 	}
95: 	if lastErr != nil {
96: 		return nil, lastErr
97: 	}
98: 	return nil, errors.New("response does not contain a complete JSON array/object")
99: }
