101: func adapterForRole(repoRoot, role string) (llm.Adapter, string, error) {
102: 	userPath, err := settings.DefaultUserPath()
103: 	if err != nil {
104: 		return nil, "", err
105: 	}
106: 	credentialPath, err := settings.DefaultCredentialsPath()
107: 	if err != nil {
108: 		return nil, "", err
109: 	}
110: 	user, err := settings.Load(userPath)
111: 	if err != nil {
112: 		return nil, "", err
113: 	}
114: 	repo, err := settings.Load(filepath.Join(repoRoot, "aegis.toml"))
115: 	if err != nil {
116: 		return nil, "", err
117: 	}
118: 	ref, _, err := settings.ResolveModel(repo, user, role)
119: 	if err != nil {
120: 		return nil, "", err
121: 	}
122: 	providerName, model, ok := strings.Cut(ref, "/")
123: 	if !ok || model == "" {
124: 		return nil, "", fmt.Errorf("%s model reference is invalid: %q", role, ref)
125: 	}
126: 	provider, ok := repo.Providers[providerName]
127: 	if !ok {
128: 		provider, ok = user.Providers[providerName]
129: 	}
130: 	if !ok {
131: 		return nil, "", fmt.Errorf("%s provider %q is not configured", role, providerName)
132: 	}
133: 	mgr := &credentials.Manager{Keyring: credentials.NewOSKeyring(), File: &credentials.FileStore{Path: credentialPath}}
134: 	key, _, err := mgr.Resolve(providerName, credentials.ProviderType(provider.Type))
135: 	if err != nil {
136: 		return nil, "", fmt.Errorf("%s provider %q is missing a key: %w", role, providerName, err)
137: 	}
138: 	switch credentials.ProviderType(provider.Type) {
139: 	case credentials.ProviderTypeAnthropic:
140: 		return llm.NewAnthropic(key, provider.BaseURL), model, nil
141: 	case credentials.ProviderTypeOpenAICompat:
142: 		if provider.BaseURL == "" {
143: 			return nil, "", fmt.Errorf("openai-compat provider %q is missing base_url", providerName)
144: 		}
145: 		return llm.NewOpenAICompat(providerName, provider.BaseURL, key, model), model, nil
146: 	default:
147: 		return nil, "", fmt.Errorf("provider %q has unsupported type %q", providerName, provider.Type)
148: 	}
149: }
