151: func roleConfigured(repoRoot, role string) bool {
152: 	userPath, err := settings.DefaultUserPath()
153: 	if err != nil {
154: 		return false
155: 	}
156: 	user, err := settings.Load(userPath)
157: 	if err != nil {
158: 		return false
159: 	}
160: 	repo, err := settings.Load(filepath.Join(repoRoot, "aegis.toml"))
161: 	if err != nil {
162: 		return false
163: 	}
164: 	_, _, err = settings.ResolveModel(repo, user, role)
165: 	return err == nil
166: }
