168: func roleText(ctx context.Context, adapter llm.Adapter, role llm.Role, model, system, prompt, effort string) (string, error) {
169: 	emitAITrace(ctx, string(role), "request", fmt.Sprintf("provider=%s model=%s effort=%s\n%s", adapter.Provider(), model, effort, prompt))
170: 	resp, err := adapter.Chat(ctx, llm.ChatRequest{Role: role, Model: model, System: system, Effort: effort,
171: 		Messages: []llm.Message{{Role: "user", Content: []llm.ContentBlock{{Type: "text", Text: prompt}}}}})
172: 	if err != nil {
173: 		return "", err
174: 	}
175: 	if resp.StopReason == llm.StopRefusal {
176: 		return "", fmt.Errorf("model %s refused to run %s (category=%s)", model, role, resp.RefusalCategory)
177: 	}
178: 	var b strings.Builder
179: 	for _, block := range resp.Content {
180: 		if block.Type == "text" {
181: 			b.WriteString(block.Text)
182: 		}
183: 	}
184: 	if strings.TrimSpace(b.String()) == "" {
185: 		return "", fmt.Errorf("model %s returned an empty %s response", model, role)
186: 	}
187: 	emitAITrace(ctx, string(role), "response", b.String())
188: 	emitAITrace(ctx, string(role), "usage", fmt.Sprintf("input=%d output=%d cache_read=%d cache_creation=%d", resp.Usage.InputTokens, resp.Usage.OutputTokens, resp.Usage.CacheReadTokens, resp.Usage.CacheCreationTokens))
189: 	return b.String(), nil
190: }
