192: // reviewJSONPayloads returns the raw response first, followed by every complete
193: // JSON array/object embedded in it. Reviewers are instructed to return JSON
194: // only, but some compatible models prepend a public summary or emit an inline
195: // ```json fence. A decoder-based extraction handles both without trying to
196: // repair or invent model output.
197: func reviewJSONPayloads(text string) []string {
198: 	text = strings.TrimSpace(text)
199: 	if text == "" {
200: 		return nil
201: 	}
202: 	payloads := []string{text}
203: 	seen := map[string]bool{text: true}
204: 	for i := 0; i < len(text); i++ {
205: 		if text[i] != '{' && text[i] != '[' {
206: 			continue
207: 		}
208: 		dec := json.NewDecoder(strings.NewReader(text[i:]))
209: 		var raw json.RawMessage
210: 		if err := dec.Decode(&raw); err != nil {
211: 			continue
212: 		}
213: 		payload := strings.TrimSpace(string(raw))
214: 		if payload != "" && !seen[payload] {
215: 			seen[payload] = true
216: 			payloads = append(payloads, payload)
217: 		}
218: 	}
219: 	return payloads
220: }
