222: func reviewableContent(file inventory.File, data []byte) bool {
223: 	if reviewableLanguage(file.Language) {
224: 		return true
225: 	}
226: 	if !utf8.Valid(data) || strings.IndexByte(string(data), 0) >= 0 {
227: 		return false
228: 	}
229: 	base := filepath.Base(file.Path)
230: 	if base == "Makefile" || base == "Procfile" || base == "Jenkinsfile" {
231: 		return true
232: 	}
233: 	switch strings.ToLower(filepath.Ext(file.Path)) {
234: 	case "", ".txt", ".csv", ".tsv", ".log", ".lock", ".map", ".md", ".rst":
235: 		return false
236: 	default:
237: 		return true // 未知但為 UTF-8 的原始碼副檔名：交由 LLM 辨識語言。
238: 	}
239: }
240: 
241: func reviewableLanguage(language string) bool {
242: 	switch language {
243: 	case "python", "go", "javascript", "typescript", "java", "kotlin", "php", "ruby", "csharp", "rust", "scala", "groovy", "elixir", "clojure", "lua", "vue", "svelte", "markup", "template", "graphql", "sql", "config", "shell", "dockerfile", "toml", "go-module":
244: 		return true
245: 	default:
246: 		return false
247: 	}
248: }
