250: func reviewFileBatches(snapshotDir string, inv *inventory.Inventory) [][]string {
251: 	var batches [][]string
252: 	var current []string
253: 	for _, file := range inv.Files {
254: 		data, err := os.ReadFile(filepath.Join(snapshotDir, filepath.FromSlash(file.Path)))
255: 		if err != nil || !reviewableContent(file, data) {
256: 			continue
257: 		}
258: 		current = append(current, file.Path)
259: 		if len(current) == 12 {
260: 			batches = append(batches, current)
261: 			current = nil
262: 		}
263: 	}
264: 	if len(current) > 0 {
265: 		batches = append(batches, current)
266: 	}
267: 	return batches
268: }
