360: func runLLMScan(ctx context.Context, repoRoot, snapshotDir, runDir, packDir string, inv *inventory.Inventory, pack *packs.Pack) ([]candidates.Candidate, error) {
361: 	reviewer, reviewerModel, err := adapterForRole(repoRoot, settings.RoleReviewer)
362: 	if err != nil {
363: 		return nil, fmt.Errorf("reviewer not wired: %w", err)
364: 	}
365: 	invJSON, _ := json.Marshal(inv)
366: 	reconSummary := "(no recon configured; reviewing directly from the inventory)"
367: 	if recon, model, reconErr := adapterForRole(repoRoot, settings.RoleRecon); reconErr == nil {
368: 		reconSummary, err = roleText(withAIPhase(ctx, "recon"), recon, llm.RoleRecon, model, "You are a read-only code surveyor; do not assume behavior for code you were not given.", "From the inventory, summarize the attack surface, frameworks, and priority review areas:\n"+string(invJSON), "low")
369: 		if err != nil {
370: 			return nil, fmt.Errorf("recon failed: %w", err)
371: 		}
372: 	}
373: 	var sinkTypes []string
374: 	for _, sink := range pack.Manifest.SinkTypes {
375: 		sinkTypes = append(sinkTypes, sink.Type)
376: 	}
377: 	taxonomy := "injection.sql, injection.command, injection.nosql, injection.template, xss, ssrf, path_traversal, file_upload, deserialization, auth.bypass, auth.session, auth.jwt, access_control.idor, access_control.privilege, csrf, crypto.weakness, secret.exposure, race_condition, business_logic, request_smuggling, open_redirect, information_exposure, denial_of_service, dependency, other"
378: 	var raw []reviewCandidate
379: 	batches := reviewFileBatches(snapshotDir, inv)
380: 	if len(batches) == 0 {
381: 		return nil, errors.New("reviewer found no text source or config files safe to submit for review")
382: 	}
383: 	registry, toolDefs, audit, err := reviewerTooling(snapshotDir, runDir, packDir, pack)
384: 	if err != nil {
385: 		return nil, fmt.Errorf("reviewer tools failed to initialize: %w", err)
386: 	}
387: 	defer audit.Close()
388: 	emitAITrace(withAIPhase(ctx, "review-plan"), string(llm.RoleReviewer), "workflow",
389: 		fmt.Sprintf("Review plan ready: %d repository files, %d exploration batch(es); tools enabled", len(inv.Files), len(batches)))
390: 	for i, files := range batches {
391: 		batchPhase := fmt.Sprintf("review-batch-%d", i+1)
392: 		emitAITrace(withAIPhase(ctx, batchPhase), string(llm.RoleReviewer), "workflow",
393: 			fmt.Sprintf("Exploring batch %d/%d: %s", i+1, len(batches), strings.Join(files, ", ")))
394: 		prompt := fmt.Sprintf("Repository reconnaissance summary:\n%s\n\nInvestigate batch %d/%d. The assigned files are:\n- %s\n\nUse read_code to inspect the assigned files and search_code to follow inputs, callers, routes, authorization checks, state changes, and sinks across the repository. Use registered Semgrep rules only when useful. Examine external input, trust boundaries, authentication/authorization, races, serialization, file/network/process sinks, and business logic; do not limit yourself to literal patterns. Before tool calls, emit a concise public progress note describing the next check and why. After investigation, return only one JSON object with analysis_summary (a public evidence-based summary, not hidden chain-of-thought) and candidates (array). Candidate fields: file, line, symbol, type, suspected_vuln_class, cwe, impact, evidence, chain, rationale, priority_hint. Suggested general types: [%s]. Exact proof-pack types when applicable: %v. Every candidate needs a real file:line and a complete input-to-impact chain; omit best-practice-only concerns. Return candidates: [] when none are supported.", reconSummary, i+1, len(batches), strings.Join(files, "\n- "), taxonomy, sinkTypes)
