457: func validReviewEvidence(snapshotDir string, values []string) []string {
458: 	var out []string
459: 	for _, value := range values {
460: 		colon := strings.LastIndex(value, ":")
461: 		if colon < 1 {
462: 			continue
463: 		}
464: 		line, err := strconv.Atoi(value[colon+1:])
465: 		if err != nil || line < 1 {
466: 			continue
467: 		}
468: 		clean := filepath.Clean(filepath.FromSlash(value[:colon]))
469: 		if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
470: 			continue
471: 		}
472: 		data, err := os.ReadFile(filepath.Join(snapshotDir, clean))
473: 		if err != nil || line > 1+strings.Count(string(data), "\n") {
474: 			continue
475: 		}
476: 		out = appendUniqueString(out, filepath.ToSlash(clean)+":"+strconv.Itoa(line))
477: 	}
478: 	return out
479: }
