95: // Watch-stream styling. The rendered output is meant to read like an agent
96: // conversation (thinking → actions → results) rather than a raw event dump.
97: // lipgloss emits ANSI only when the destination is a real terminal (the TUI or
98: // an interactive --watch); piped/redirected output and `go test` degrade to
99: // plain text, so substring assertions and log redirection stay clean.
100: var (
101: 	stThink    = lipgloss.NewStyle().Foreground(lipgloss.Color("#A78BFA")).Bold(true)
102: 	stThinkTxt = lipgloss.NewStyle().Foreground(lipgloss.Color("#B9A7F0")).Italic(true)
103: 	stTool     = lipgloss.NewStyle().Foreground(lipgloss.Color("#4FD1C5")).Bold(true)
104: 	stPhase    = lipgloss.NewStyle().Foreground(lipgloss.Color("#48BB78")).Bold(true)
105: 	stAnswer   = lipgloss.NewStyle().Foreground(lipgloss.Color("#E6EDEB"))
106: 	stDim      = lipgloss.NewStyle().Foreground(lipgloss.Color("#6B7A77"))
