110: // formatWatchEvent renders one audit event as a single conversational block for
111: // the live watch stream. It intentionally never prints full prompts, source
112: // bundles, or raw tool results — ai-events.jsonl keeps the complete redacted
113: // record; the terminal shows the agent's reasoning and actions, not a data dump.
114: //
115: // Returning "" drops an event from the visible stream (kept in the audit log):
116: // outbound-payload sizes and token accounting are log detail, not operator
117: // signal, and would otherwise bury the thinking-and-tools narrative in noise.
118: func formatWatchEvent(event aiTraceEvent) string {
119: 	label := event.Role
120: 	if event.Phase != "" {
121: 		label += " · " + event.Phase
122: 	}
123: 	switch event.Kind {
124: 	case "request", "usage":
125: 		return ""
126: 	case "workflow":
127: 		// A phase boundary: a blank line then a bright header, so the transcript
128: 		// reads in scannable sections rather than one unbroken wall.
129: 		return "\n" + stPhase.Render("● "+oneLine(event.Content, 400)) + "  " + stDim.Render("("+label+")")
130: 	case "commentary":
131: 		// The agent's public progress note before a group of tool calls — the
132: 		// visible "thinking" the operator wants to follow. Drop the "turn N:"
133: 		// bookkeeping prefix and show it as a readable, indented block.
134: 		text := event.Content
135: 		if strings.HasPrefix(text, "turn ") {
136: 			if _, rest, ok := strings.Cut(text, ": "); ok {
137: 				text = rest
138: 			}
139: 		}
140: 		return stThink.Render("💭 "+label) + "\n" + indentLines(stThinkTxt.Render(oneLine(text, 1000)), "   ")
141: 	case "response":
142: 		if summary, count, ok := structuredResponseSummary(event.Content); ok {
143: 			return stTool.Render("⏺") + " " + stAnswer.Render(oneLine(summary, 600)) +
144: 				" " + stDim.Render(fmt.Sprintf("(%d candidate(s))", count))
145: 		}
146: 		if strings.HasPrefix(event.Phase, "prove-") || event.Phase == "report" {
147: 			// Long structured artifacts (proofs, reports) land in files; a
148: 			// byte-count line here is noise.
149: 			return ""
150: 		}
151: 		return stTool.Render("⏺") + " " + stAnswer.Render(oneLine(event.Content, 800))
152: 	case "tool_call":
153: 		tool, args, _ := strings.Cut(event.Content, " ")
154: 		return stTool.Render("⏺ "+tool) + " " + stDim.Render(summarizeToolCall(tool, args))
155: 	case "tool_result":
156: 		if strings.HasPrefix(event.Content, "ERROR ") {
157: 			return "  " + stErr.Render("⎿ error: "+oneLine(strings.TrimPrefix(event.Content, "ERROR "), 300))
158: 		}
159: 		tool, result, _ := strings.Cut(event.Content, " ")
160: 		return "  " + stDim.Render("⎿ "+summarizeToolResult(tool, result))
161: 	default:
162: 		if strings.HasPrefix(event.Kind, "tool_") {
163: 			return "  " + stDim.Render("⎿ "+event.Kind+" ("+humanBytes(len(event.Content))+")")
164: 		}
165: 		return stDim.Render("• " + label + " · " + event.Kind + " — " + oneLine(event.Content, 400))
166: 	}
167: }
