179: func structuredResponseSummary(content string) (string, int, bool) {
180: 	var envelope struct {
181: 		AnalysisSummary string            `json:"analysis_summary"`
182: 		Candidates      []json.RawMessage `json:"candidates"`
183: 	}
184: 	payload := strings.TrimSpace(content)
185: 	if strings.HasPrefix(payload, "```") {
186: 		if newline := strings.IndexByte(payload, '\n'); newline >= 0 {
187: 			payload = payload[newline+1:]
188: 		}
189: 		payload = strings.TrimSuffix(strings.TrimSpace(payload), "```")
190: 	}
191: 	if json.Unmarshal([]byte(payload), &envelope) == nil && envelope.AnalysisSummary != "" {
192: 		return envelope.AnalysisSummary, len(envelope.Candidates), true
193: 	}
194: 	var candidates []json.RawMessage
195: 	if json.Unmarshal([]byte(payload), &candidates) == nil {
196: 		return "Structured candidate list received", len(candidates), true
197: 	}
198: 	return "", 0, false
