1135: func commandBuildApprover(cmd *cobra.Command, preapproved bool) approval.Approver {
1136: 	allowAll := preapproved
1137: 	inherited := approval.FromContext(cmd.Context())
1138: 	return func(req approval.BuildRequest) (approval.Decision, error) {
1139: 		if allowAll {
1140: 			return approval.AllowRun, nil
1141: 		}
1142: 		if inherited != nil {
1143: 			decision, err := inherited(req)
1144: 			if decision == approval.AllowRun {
1145: 				allowAll = true
1146: 			}
1147: 			return decision, err
1148: 		}
1149: 		inFile, inOK := cmd.InOrStdin().(*os.File)
1150: 		outFile, outOK := cmd.OutOrStdout().(*os.File)
1151: 		if !inOK || !outOK || !term.IsTerminal(int(inFile.Fd())) || !term.IsTerminal(int(outFile.Fd())) {
1152: 			return approval.Deny, errors.New("非互動環境不會自動建立 image；請加 --approve-build 明確核准")
1153: 		}
1154: 		decision, err := approval.Prompt(inFile, outFile, req)
1155: 		if decision == approval.AllowRun {
1156: 			allowAll = true
1157: 		}
1158: 		return decision, err
1159: 	}
1160: }
