1473: func packCoverage(pack *packs.Pack, inv *inventory.Inventory, reviewer bool) coverageRecord {
1474: 	allowed, target, targetLanguages := map[string]bool{}, map[string]bool{}, map[string]bool{}
1475: 	for _, tmpl := range pack.Manifest.Templates {
1476: 		for _, ext := range tmpl.AllowedFiles {
1477: 			allowed[strings.ToLower(ext)] = true
1478: 		}
1479: 	}
1480: 	for _, file := range inv.Files {
1481: 		if file.Language == "other" || file.Language == "toml" || file.Language == "go-module" {
1482: 			continue
1483: 		}
1484: 		if ext := strings.ToLower(filepath.Ext(file.Path)); ext != "" {
1485: 			target[ext] = true
1486: 			targetLanguages[file.Language] = true
1487: 		}
1488: 	}
1489: 	matched, uncovered := map[string]bool{}, map[string]bool{}
1490: 	for ext := range target {
1491: 		if allowed[ext] {
1492: 			matched[ext] = true
1493: 		} else {
1494: 			uncovered[ext] = true
1495: 		}
1496: 	}
1497: 	record := coverageRecord{PackID: pack.Manifest.PackID, PackVersion: pack.Manifest.Version,
1498: 		VerifiableExtensions: stringsToSortedSlice(allowed), ProofRuntimeExtensions: stringsToSortedSlice(allowed), TargetExtensions: stringsToSortedSlice(target), TargetLanguages: stringsToSortedSlice(targetLanguages),
1499: 		MatchedExtensions: stringsToSortedSlice(matched), UncoveredExtensions: stringsToSortedSlice(uncovered),
1500: 		LLMReviewerConfigured: reviewer, DiscoveryMode: "detectors-only"}
1501: 	if reviewer {
1502: 		record.DiscoveryMode = "llm-global-review+detectors"
1503: 	}
1504: 	for _, detector := range pack.Manifest.Detectors {
1505: 		record.DetectorIDs = append(record.DetectorIDs, detector.ID)
1506: 		record.DetectorLanguages = append(record.DetectorLanguages, detector.Languages...)
1507: 	}
1508: 	for _, sink := range pack.Manifest.SinkTypes {
1509: 		record.SinkTypes = append(record.SinkTypes, sink.Type)
1510: 	}
1511: 	proofFamilies := map[string]bool{}
1512: 	for _, tmpl := range pack.Manifest.Templates {
1513: 		for _, oracle := range pack.Manifest.Oracles {
1514: 			if tmpl.Family == oracle.Family && oracle.Touch != nil {
1515: 				proofFamilies[tmpl.Family] = true
1516: 			}
1517: 		}
1518: 	}
1519: 	record.ProofFamilies = stringsToSortedSlice(proofFamilies)
1520: 	sort.Strings(record.DetectorIDs)
1521: 	record.DetectorLanguages = stringsToSortedSlice(stringSliceMap(record.DetectorLanguages))
1522: 	sort.Strings(record.SinkTypes)
1523: 	return record
1524: }
