269: 		t.Fatalf("audit 行非法：%v（%q）", err, last)
270: 	}
271: 	if e.Tool != tool || e.Decision != want {
272: 		t.Fatalf("audit 不符：tool=%q decision=%q，want %q/%q", e.Tool, e.Decision, tool, want)
273: 	}
