276: func nonEmptyLines(s string) []string {
277: 	var out []string
278: 	start := 0
279: 	for i := 0; i <= len(s); i++ {
280: 		if i == len(s) || s[i] == '\n' {
281: 			if i > start {
282: 				out = append(out, s[start:i])
283: 			}
284: 			start = i + 1
285: 		}
286: 	}
287: 	return out
288: }
