103: // 回傳的 Config 的兩個 map 恆為非 nil，呼叫端可直接寫入。
104: func Load(path string) (*Config, error) {
105: 	cfg := &Config{
106: 		Providers: map[string]Provider{},
107: 		Models:    map[string]string{},
108: 	}
109: 	data, err := os.ReadFile(path)
110: 	if err != nil {
111: 		if errors.Is(err, os.ErrNotExist) {
112: 			return cfg, nil
113: 		}
114: 		return nil, fmt.Errorf("settings: read %s: %w", path, err)
115: 	}
116: 	// 非嚴格解碼：aegis.toml 內的 [budget]/[sandbox]/[sink_packs] 等節
117: 	//（§5.4）由各自的包負責，此處靜默略過未知鍵。
118: 	if err := toml.Unmarshal(data, cfg); err != nil {
119: 		return nil, fmt.Errorf("settings: parse %s: %w", path, err)
120: 	}
121: 	if cfg.Providers == nil {
122: 		cfg.Providers = map[string]Provider{}
123: 	}
124: 	if cfg.Models == nil {
125: 		cfg.Models = map[string]string{}
126: 	}
127: 	return cfg, nil
128: }
129: 
130: // SaveUser 將 cfg 以 TOML 寫入 path（使用者層級檔，如 settings.toml）。
131: //
132: //   - 先 MkdirAll 父目錄（~/.config/aegis 可能尚不存在，§3.3 首次執行流程）。
133: //   - 檔案權限 0600：使用者層級檔可能與 credentials.toml 同目錄，取 restrictive
134: //     慣例（§3.3 credentials.toml 亦為 0600）；測試鎖定此 mode。
135: //   - 鍵序確定性：BurntSushi/toml 的 Encoder 對 map 鍵一律排序輸出，故同一
136: //     cfg 兩次寫出位元組相同；本包另以 sort 明確排序 provider/model 名再交由
137: //     Encoder（見 encodeSorted），保證 byte-stable 不依賴函式庫實作細節。
138: func SaveUser(path string, c *Config) error {
139: 	if c == nil {
140: 		c = &Config{}
141: 	}
142: 	if dir := filepath.Dir(path); dir != "" && dir != "." {
143: 		if err := os.MkdirAll(dir, 0o700); err != nil {
144: 			return fmt.Errorf("settings: mkdir %s: %w", dir, err)
145: 		}
146: 	}
147: 	out, err := encodeSorted(c)
148: 	if err != nil {
149: 		return fmt.Errorf("settings: encode %s: %w", path, err)
150: 	}
151: 	if err := os.WriteFile(path, out, 0o600); err != nil {
152: 		return fmt.Errorf("settings: write %s: %w", path, err)
153: 	}
154: 	return nil
155: }
156: 
157: // encodeSorted 以「排序後的鍵序」把 c 編成 TOML 位元組。
158: // 作法：先按鍵排序組出確定順序的 map（BurntSushi Encoder 本身會排序 map 鍵，
159: // 此處顯式排序僅為把確定性寫進本包契約，不依賴函式庫行為），再交 Encoder。
160: // 空的 providers/models 不輸出任何節，檔案保持最小。
161: func encodeSorted(c *Config) ([]byte, error) {
162: 	providers := map[string]Provider{}
163: 	for _, name := range sortedKeys(c.Providers) {
164: 		providers[name] = c.Providers[name]
165: 	}
166: 	models := map[string]string{}
167: 	for _, role := range sortedKeys(c.Models) {
168: 		models[role] = c.Models[role]
169: 	}
170: 	doc := struct {
171: 		Providers map[string]Provider `toml:"providers"`
172: 		Models    map[string]string   `toml:"models"`
173: 		Budget    Budget              `toml:"budget,omitempty"`
174: 		UI        UI                  `toml:"ui,omitempty"`
175: 	}{Providers: providers, Models: models, Budget: c.Budget, UI: c.UI}
176: 	var buf strings.Builder
177: 	if err := toml.NewEncoder(&buf).Encode(doc); err != nil {
178: 		return nil, err
179: 	}
180: 	return []byte(buf.String()), nil
181: }
182: 
183: // sortedKeys 回傳 map 的鍵、升冪排序（byte-stable 輸出的真源）。
184: func sortedKeys[V any](m map[string]V) []string {
185: 	keys := make([]string, 0, len(m))
186: 	for k := range m {
187: 		keys = append(keys, k)
188: 	}
189: 	sort.Strings(keys)
190: 	return keys
191: }
192: 
193: // ResolveModel 依 §3.1 解析序回傳 role 的模型引用：
194: // repo aegis.toml > 使用者 settings.toml > 無。
195: // 回傳值 ref 為 "<provider>/<model-id>"，source 為 "repo" | "user" | ""；
196: // 兩層皆無定義時回傳 ("", "", ErrModelUnset)。
197: //
198: // ASK（§23-9）：spec 未規定 repo/user 層「已設定但引用不合法」時的行為。
199: // 目前採不驗證、原樣回傳，由呼叫端自行以 ValidateRef 檢查（選項：
200: // (a) 維持現狀——ResolveModel 純查表；(b) 在此先跑 ValidateRef、不合法即回錯；
201: // (c) 回傳 ref 並附第二個 error 欄位）。待人類決定後調整。
202: func ResolveModel(repo, user *Config, role string) (ref string, source string, err error) {
203: 	if repo != nil {
204: 		if r, ok := repo.Models[role]; ok {
205: 			return r, "repo", nil
206: 		}
207: 	}
208: 	if user != nil {
209: 		if r, ok := user.Models[role]; ok {
210: 			return r, "user", nil
211: 		}
212: 	}
213: 	return "", "", fmt.Errorf("settings: %w (role=%q)", ErrModelUnset, role)
214: }
215: 
216: // ValidateRef 檢查 ref 是否為 §3.1 模型引用語法 "<provider>/<model-id>"：
217: // 必須含一個 '/' 分隔符，provider 與 model-id 兩段皆非空，且整串無任何空白。
218: // ASK（§23-9）：model-id 內是否允許再含 '/'（如 OpenRouter 的
219: // "vendor/family/name" 深層 id）spec 未定義。目前採以「第一個 '/'」切分、
220: // model-id 段可含 '/'（寬鬆，不誤擋合法 id）；若人類決定閉集單層，改為
221: // strings.Count == 1 即可。
222: func ValidateRef(ref string) error {
223: 	if strings.TrimSpace(ref) != ref || strings.ContainsAny(ref, " \t\n\r\v\f") {
224: 		return fmt.Errorf("settings: model ref %q must not contain whitespace", ref)
225: 	}
226: 	provider, modelID, ok := strings.Cut(ref, "/")
227: 	if !ok || provider == "" || modelID == "" {
228: 		return fmt.Errorf("settings: model ref %q must be \"<provider>/<model-id>\"", ref)
229: 	}
230: 	return nil
231: }
232: 
233: // DefaultUserDir 回傳使用者層級設定目錄（§3.3：~/.config/aegis）：
234: // $XDG_CONFIG_HOME（需為絕對路徑，依 XDG 規範相對值視同未設）或
235: // ~/.config（經 os.UserHomeDir，HOME 變動即生效），再接 "aegis"。
236: func DefaultUserDir() (string, error) {
237: 	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" && filepath.IsAbs(xdg) {
238: 		return filepath.Join(xdg, "aegis"), nil
239: 	}
240: 	home, err := os.UserHomeDir()
241: 	if err != nil {
242: 		return "", fmt.Errorf("settings: resolve user config dir: %w", err)
243: 	}
244: 	return filepath.Join(home, ".config", "aegis"), nil
245: }
246: 
247: // DefaultUserPath 回傳使用者層級設定檔路徑（§3.3：settings.toml，
248: // /model set 的寫入處）。
249: func DefaultUserPath() (string, error) {
250: 	dir, err := DefaultUserDir()
251: 	if err != nil {
252: 		return "", err
253: 	}
254: 	return filepath.Join(dir, "settings.toml"), nil
255: }
256: 
257: // DefaultCredentialsPath 回傳 keychain 不可用時的憑證退回檔路徑
258: // （§3.3：credentials.toml，0600）。本包只定路徑，不讀寫內容。
259: func DefaultCredentialsPath() (string, error) {
260: 	dir, err := DefaultUserDir()
261: 	if err != nil {
262: 		return "", err
263: 	}
264: 	return filepath.Join(dir, "credentials.toml"), nil
265: }
