10: // osKeyring 以 github.com/zalando/go-keyring 包裝 OS keychain（§23 相依表：
11: // 統一 macOS Keychain / Linux libsecret / Windows Credential Manager；
12: // 不可用時由 Manager.Set 退回 §3.3 的檔案模式）。macOS 走 `security`
13: // 子指令、無 cgo，可直接建置。service 名固定為 KeyringService（"aegis"）。
14: type osKeyring struct{}
15: 
16: // NewOSKeyring 回傳 OS keychain 後端（§3.3 keychain 儲存）。
17: // go-keyring 的 ErrNotFound 一律正規化為本包的 ErrKeyNotFound。
18: func NewOSKeyring() Keyring { return osKeyring{} }
