40: // Manager 統合 §3.3 的憑證解析序：環境變數 > OS keychain > 設定檔退回。
41: // 金鑰內容只經 Resolve 回傳一次給呼叫端（host 端 adapter 使用），
42: // Status 只回報有無與來源、永不回傳內容（§3.3 /provider list）。
43: type Manager struct {
44: 	// Keyring 為 OS keychain 後端；nil 表示無 keychain 環境（僅檔案退回）。
45: 	Keyring Keyring
46: 	// File 為設定檔退回儲存（§3.3 credentials.toml，0600）；可為 nil。
47: 	File *FileStore
48: 	// Environ 為環境變數讀取函式；nil 時使用 os.Getenv（測試可注入假環境）。
49: 	Environ func(string) string
50: }
51: 
52: // Resolve 依 §3.3 解析序取金鑰：環境變數（正規化名優先、慣用相容名其後）>
53: // OS keychain（若 Keyring != nil）> 檔案退回（若 File != nil）。
54: // source ∈ "env" | "keychain" | "file"；找不到時 key 與 source 為空、
55: // err = ErrKeyNotFound。
56: func (m *Manager) Resolve(providerName string, pt ProviderType) (key string, source string, err error) {
57: 	// 1) 環境變數（§3.3：AEGIS_<供應商大寫>_API_KEY，並相容辨識慣用名）。
58: 	for _, name := range envCandidates(providerName, pt) {
59: 		if v := m.getenv(name); v != "" {
60: 			return v, "env", nil
61: 		}
62: 	}
63: 	// 2) OS keychain（§3.3）。
64: 	if m.Keyring != nil {
65: 		k, err := m.Keyring.Get(KeyringService, providerName)
66: 		if err == nil {
67: 			return k, "keychain", nil
68: 		}
69: 		if !errors.Is(err, ErrKeyNotFound) {
70: 			// ASK: keychain 查詢失敗（非「不存在」）時的處理。採 (a) 視同 miss、
71: 			// 續查檔案退回——符合 §3.3「無 keychain 環境退回設定檔」的精神，
72: 			// 且解析失敗不該因單一後端故障而中斷。選項 (b)：直接回傳該錯誤中斷解析
73: 			//（較早暴露後端故障，但無 keychain 機器的整條解析會硬失敗）。
74: 		}
75: 	}
76: 	// 3) 設定檔退回（§3.3：credentials.toml，0600，使用時警告一次）。
77: 	if m.File != nil {
78: 		k, err := m.File.Get(providerName)
79: 		if err == nil {
80: 			return k, "file", nil
81: 		}
82: 		if !errors.Is(err, ErrKeyNotFound) {
83: 			// 非「不存在」的錯誤（檔案損毀、無權限）如實上拋——靜默吞掉會讓
84: 			// 呼叫端誤判為「未設定金鑰」。
85: 			return "", "", err
86: 		}
87: 	}
88: 	return "", "", ErrKeyNotFound
89: }
90: 
91: // Set 依 §3.3 寫入 OS keychain（/key set）；keychain 不可用（Set 回傳任何錯誤）
92: // 時退回檔案模式（§23 相依表：不可用時退回 §3.3 的檔案模式）。
93: // Keyring 為 nil 時僅寫檔案。
94: func (m *Manager) Set(providerName string, pt ProviderType, key string) error {
95: 	if m.Keyring != nil {
96: 		err := m.Keyring.Set(KeyringService, providerName, key)
97: 		if err == nil {
98: 			return nil
99: 		}
100: 		if m.File == nil {
101: 			return fmt.Errorf("credentials: keychain set failed: %w", err)
102: 		}
103: 		if ferr := m.File.Set(providerName, key); ferr != nil {
104: 			return fmt.Errorf("credentials: keychain set failed (%v); file fallback failed: %w", err, ferr)
105: 		}
106: 		// ASK: keychain 失敗但檔案退回成功時的回傳值。採 (a) 回傳 nil——
107: 		// 金鑰已成功落盤，呼叫端不應視為失敗；使用檔案時 FileStore 會在使用時
108: 		// 自行警告一次（§3.3）。選項 (b)：仍回傳包裝 keychain 錯誤的非 nil 值，
109: 		// 讓互動模式能把「已退回檔案模式」提示給使用者（需呼叫端容忍
110: 		// 「非 nil 但其實已寫入」的語意）。
111: 		return nil
112: 	}
113: 	// 無 keychain（Keyring nil）→ 僅寫檔案（§3.3 設定檔退回）。
114: 	if m.File == nil {
115: 		return errors.New("credentials: no keyring and no file store configured")
116: 	}
117: 	return m.File.Set(providerName, key)
118: }
119: 
120: // Clear 刪除已存 token（§3.3 /key clear、/provider remove 連同 keychain 金鑰）：
121: // keychain 與檔案退回都清；「不存在」視為成功（冪等）。其他錯誤回傳第一個。
122: func (m *Manager) Clear(providerName string, pt ProviderType) error {
123: 	var firstErr error
124: 	if m.Keyring != nil {
125: 		if err := m.Keyring.Delete(KeyringService, providerName); err != nil && !errors.Is(err, ErrKeyNotFound) && firstErr == nil {
126: 			firstErr = err
127: 		}
128: 	}
129: 	if m.File != nil {
130: 		if err := m.File.Delete(providerName); err != nil && !errors.Is(err, ErrKeyNotFound) && firstErr == nil {
131: 			firstErr = err
132: 		}
133: 	}
134: 	return firstErr
135: }
136: 
137: // Status 回報金鑰是否已設定及其來源，永不回傳金鑰內容
138: //（§3.3 /provider list 只顯示有無，永不顯示內容）。
139: func (m *Manager) Status(providerName string, pt ProviderType) (set bool, source string) {
140: 	key, source, err := m.Resolve(providerName, pt)
141: 	if err != nil {
142: 		return false, ""
143: 	}
144: 	_ = key // 內容即棄：本方法的合約是不外洩金鑰（§3.3）。
145: 	return true, source
146: }

read_code 1: // Package observerproxy is the trusted SQL observer protocol.
2: //
3: // The proxy owns the SQLite connection and trace file.  A witness only gets a
4: // narrow request/response socket; it never gets a path to the trusted output.
5: // The server is deliberately sequential in v1 (SPEC §23-1).
6: package observerproxy
7: 
8: import (
9: 	"bufio"
10: 	"context"
11: 	"database/sql"
12: 	"encoding/json"
13: 	"fmt"
14: 	"net"
15: 	"os"
16: 	"sync"
17: 	"time"
18: 
19: 	"github.com/aegis-dev/aegis/internal/evidence"
20: 	_ "modernc.org/sqlite"
21: )
22: 
23: type Request struct {
24: 	Op     string `json:"op"`
25: 	SQL    string `json:"sql"`
26: 	Params []any  `json:"params,omitempty"`
27: }
28: 
29: type Response struct {
30: 	OK      bool     `json:"ok"`
31: 	Rows    [][]any  `json:"rows,omitempty"`
32: 	Columns []string `json:"columns,omitempty"`
33: 	Error   string   `json:"error,omitempty"`
34: }
35: 
36: // Server owns the trusted database and trace output.
37: type Server struct {
38: 	db   *sql.DB
39: 	file *os.File
40: 	mu   sync.Mutex
41: }
42: 
43: func Open(dbPath, tracePath string) (*Server, error) {
44: 	db, err := sql.Open("sqlite", "file:"+dbPath)
45: 	if err != nil {
46: 		return nil, fmt.Errorf("observer: open sqlite: %w", err)
47: 	}
48: 	f, err := os.OpenFile(tracePath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
49: 	if err != nil {
50: 		_ = db.Close()
51: 		return nil, fmt.Errorf("observer: open trace: %w", err)
52: 	}
53: 	return &Server{db: db, file: f}, nil
54: }
55: 
56: func (s *Server) Close() error {
57: 	if s == nil {
58: 		return nil
59: 	}
60: 	if s.file != nil {
61: 		_ = s.file.Close()
62: 	}
63: 	if s.db != nil {
64: 		return s.db.Close()
65: 	}
66: 	return nil
67: }
68: 
69: // Serve handles one JSON request per accepted connection.  It uses listener
70: // deadlines so cancellation is observed without a background goroutine.
71: func (s *Server) Serve(ctx context.Context, ln net.Listener) error {
72: 	defer ln.Close()
73: 	for {
74: 		if dl, ok := ln.(interface{ SetDeadline(time.Time) error }); ok {
75: 			if err := dl.SetDeadline(time.Now().Add(250 * time.Millisecond)); err != nil {
76: 				return err
77: 			}
78: 		}
79: 		conn, err := ln.Accept()
80: 		if err != nil {
81: 			if ne, ok := err.(net.Error); ok && ne.Timeout() {
82: 				if ctx.Err() != nil {
83: 					return ctx.Err()
84: 				}
85: 				continue
86: 			}
87: 			if ctx.Err() != nil {
88: 				return ctx.Err()
89: 			}
90: 			return err
91: 		}
92: 		s.handle(conn)
93: 		_ = conn.Close()
94: 	}
95: }
96: 
97: func (s *Server) handle(conn net.Conn) {
98: 	var req Request
99: 	err := json.NewDecoder(bufio.NewReader(conn)).Decode(&req)
100: 	var resp Response
101: 	if err != nil {
102: 		resp = Response{Error: "bad request"}
103: 	} else {
104: 		resp = s.execute(req)
105: 	}
106: 	_ = json.NewEncoder(conn).Encode(resp)
107: }
108: 
109: func (s *Server) execute(req Request) Response {
110: 	if req.Op != "execute" || req.SQL == "" {
111: 		return Response{Error: "invalid observer request"}
112: 	}
113: 	s.mu.Lock()
114: 	defer s.mu.Unlock()
115: 	args := make([]any, len(req.Params))
116: 	copy(args, req.Params)
117: 	ts := time.Now().UTC().Format(time.RFC3339Nano)
118: 	var rows [][]any
119: 	var cols []string
120: 	var runErr error
121: 	if isQuery(req.SQL) {
122: 		var rs *sql.Rows
123: 		rs, runErr = s.db.Query(req.SQL, args...)
124: 		if runErr == nil {
125: 			cols, runErr = rs.Columns()
126: 			for rs.Next() {
127: 				vals := make([]any, len(cols))
128: 				dest := make([]any, len(cols))
129: 				for i := range vals {
130: 					dest[i] = &vals[i]
131: 				}
132: 				if err := rs.Scan(dest...); err != nil {
133: 					runErr = err
134: 					break
135: 				}
136: 				rows = append(rows, vals)
137: 			}
138: 			if err := rs.Err(); err != nil {
139: 				runErr = err
140: 			}
141: 			_ = rs.Close()
142: 		}
143: 	} else {
144: 		_, runErr = s.db.Exec(req.SQL, args...)
145: 	}
146: 	entry := map[string]any{"ts": ts, "sql": req.SQL, "params": req.Params, "error": nil, "rows": len(rows)}
147: 	if runErr != nil {
148: 		entry["error"] = runErr.Error()
149: 	}
150: 	if raw, err := evidence.CanonicalBytes(entry); err == nil {
151: 		_, _ = s.file.Write(append(raw, '\n'))
152: 	}
153: 	if runErr != nil {
154: 		return Response{Error: runErr.Error()}
155: 	}
156: 	return Response{OK: true, Rows: rows, Columns: cols}
157: }
