159: func isQuery(sqlText string) bool {
160: 	for len(sqlText) > 0 && (sqlText[0] == ' ' || sqlText[0] == '\n' || sqlText[0] == '\r' || sqlText[0] == '\t') {
161: 		sqlText = sqlText[1:]
162: 	}
163: 	if len(sqlText) < 6 {
164: 		return false
165: 	}
166: 	for i, want := range "select" {
167: 		c := sqlText[i]
168: 		if c >= 'A' && c <= 'Z' {
169: 			c += 'a' - 'A'
170: 		}
171: 		if c != byte(want) {
172: 			return false
173: 		}
174: 	}
175: 	return len(sqlText) == 6 || sqlText[6] == ' ' || sqlText[6] == '\n' || sqlText[6] == '\t'
176: }
